catch(Throwable){if($tariffNativePost)$tariffHandled=true;http_response_code(503);$error=$tariffAcceptStarted?'Tarifausgang nicht bestätigt. Die ursprüngliche Bestätigung über ihre Kennung prüfen.':'Tarife konnten nicht geladen werden.';}
